import{_ as s,o as a,c as e,ai as i}from"./chunks/framework.Ba-VnP44.js";const g=JSON.parse('{"title":"把个人网站从「学习站」改造成「求职作品集」：导航重构与死链治理","description":"","frontmatter":{"title":"把个人网站从「学习站」改造成「求职作品集」：导航重构与死链治理","outline":"deep"},"headers":[],"relativePath":"tech-system/frontend/site-refactor-job-portfolio.md","filePath":"tech-system/frontend/site-refactor-job-portfolio.md"}'),r={name:"tech-system/frontend/site-refactor-job-portfolio.md"};function n(l,t,d,o,h,p){return a(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="把个人网站从「学习站」改造成「求职作品集」" tabindex="-1">把个人网站从「学习站」改造成「求职作品集」 <a class="header-anchor" href="#把个人网站从「学习站」改造成「求职作品集」" aria-label="Permalink to “把个人网站从「学习站」改造成「求职作品集」”">​</a></h1><blockquote><p>本文记录一次真实的信息架构重构：把一个堆了 445 篇笔记、顶部 6 个栏目（含 2 个下拉）、侧栏按旧目录散装的个人站，改造成面向求职的 5 栏目作品集。所有数字来自本次真实改动，方法可复现。</p></blockquote><h2 id="一、问题背景" tabindex="-1">一、问题背景 <a class="header-anchor" href="#一、问题背景" aria-label="Permalink to “一、问题背景”">​</a></h2><p>原站点定位是「个人技术学习站」：顶部 6 个一级栏目、其中 2 个用下拉承载二级分类、还有一个独立的「开源拆解」栏目；左侧菜单按旧目录（guide / java / database / redis / framework / mq……）各配一套。结果是：</p><ul><li><strong>访客 10 秒内看不懂这个站是干什么的</strong>——对求职毫无帮助；</li><li>同一个人的内容散在十几套侧栏里，Java 知识被拆到 <code>java/</code>、<code>framework/</code>、<code>springboot/</code> 三个目录；</li><li>早年一次目录迁移后，正文里残留了 <strong>22 个死链</strong>（指向已被删除的旧 AI 文档），没人发现；</li><li>公司项目（MES / CRM / AI 漫剧）和可公开验证的开源项目混在一起，没有区分。</li></ul><p><strong>目标</strong>：一天内完成页面框架改造，让站点能直接用于求职展示——顶部只留 5 个栏目、每栏目独立侧栏、首页突出个人定位与代表项目；<strong>不动任何一篇文章的 URL</strong>。</p><h2 id="二、方案比较与关键决策" tabindex="-1">二、方案比较与关键决策 <a class="header-anchor" href="#二、方案比较与关键决策" aria-label="Permalink to “二、方案比较与关键决策”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>取舍</th></tr></thead><tbody><tr><td>A. 大搬家</td><td>按新分类物理移动/重命名 md 文件</td><td>目录整齐，但 <strong>URL 全变、外链全失效、回归风险高</strong></td></tr><tr><td>B. 只改配置</td><td>不动文件，只用 VitePress 的 nav/sidebar 重新组织展示</td><td>URL 零变更、可整体回退；代价是物理目录仍保留旧名</td></tr><tr><td>C. 折中</td><td>配置重组 + 未归类内容用 <code>/more/</code> 兜底</td><td>兼顾「框架稳定」与「不丢内容」</td></tr></tbody></table><p>选 <strong>C</strong>。核心原则：<strong>改造第一天不迁移任何文件</strong>，只改 <code>config.mts</code> 的导航与侧栏，让 445 篇文章「换件衣服」而不「搬家」。未归类的就业/成长/英语/资源类内容（约 150 篇）先通过一个低调的 <code>/more/</code> 入口保持可达，后续再治理。</p><h2 id="三、关键实现" tabindex="-1">三、关键实现 <a class="header-anchor" href="#三、关键实现" aria-label="Permalink to “三、关键实现”">​</a></h2><h3 id="_3-1-顶部收敛为-5-栏目、零下拉" tabindex="-1">3.1 顶部收敛为 5 栏目、零下拉 <a class="header-anchor" href="#_3-1-顶部收敛为-5-栏目、零下拉" aria-label="Permalink to “3.1 顶部收敛为 5 栏目、零下拉”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>改造前：首页 / 技术体系(下拉) / 开源拆解 / 应用开发(下拉) / AI赋能 / 关于我   （6 项，2 个下拉）</span></span>
<span class="line"><span>改造后：首页 / 应用实例 / 功能开发 / 技术体系 / AI 实践 / 关于我               （6 项，0 下拉）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>后续演进（2026-10-23）：新增「应用实例」一级栏目承载规划项目矩阵（5 模块 × 3 项目，均为配置与页面调整，无文件迁移）；原「应用开发」更名为「功能开发」，与「应用实例」形成「规划项目 ↔ 技术实践」的分工。URL 依旧零变更。</p></blockquote><p>二级分类全部下沉到左侧菜单。「开源拆解」不再占一级入口，但其 4 个页面内容保留、仍可访问。</p><h3 id="_3-2-每栏目一套独立侧栏" tabindex="-1">3.2 每栏目一套独立侧栏 <a class="header-anchor" href="#_3-2-每栏目一套独立侧栏" aria-label="Permalink to “3.2 每栏目一套独立侧栏”">​</a></h3><ul><li><strong>功能开发</strong>：企业业务 / 工业数字化 / AI 应用 / 办公自动化 / 个人工具</li><li><strong>技术体系</strong>：Java 后端 / 前端工程 / 数据库与中间件 / 系统集成 / 工业与物联网 / 部署与运维（把原先散在 <code>java</code> <code>framework</code> <code>springboot</code> <code>database</code> <code>redis</code> <code>mq</code> 的 38+34 篇归位）</li><li><strong>AI 实践</strong>：辅助编程 / Agent / 知识库与 RAG / 工作流 / 应用案例</li><li><strong>关于我</strong>：个人介绍 / 工作经历 / 技术能力 / 简历与联系</li></ul><p>侧栏 link 仍指向<strong>原 md 路径</strong>，所以文章 URL 一个都没变。</p><h3 id="_3-3-未归类内容的「内容映射表」" tabindex="-1">3.3 未归类内容的「内容映射表」 <a class="header-anchor" href="#_3-3-未归类内容的「内容映射表」" aria-label="Permalink to “3.3 未归类内容的「内容映射表」”">​</a></h3><p>没有为了填满菜单而造空页面。先建一张映射表（原路径 / 篇数 / 当前归属 / 目标归属 / 是否迁移 / URL 风险），没有明确归属的统一进 <code>/more/</code>，<strong>原路径全部保留可达</strong>。</p><h2 id="四、验证-死链治理" tabindex="-1">四、验证：死链治理 <a class="header-anchor" href="#四、验证-死链治理" aria-label="Permalink to “四、验证：死链治理”">​</a></h2><p>改造最怕「改了导航却留下一堆死链」。我没有只信 VitePress 的 dead-link 警告，而是<strong>从构建产物里实证</strong>：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 提取所有渲染后页面的站内链接</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -roh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;href=&quot;/my-vitepress-site/[^&quot;#?]*&quot;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.html&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/href=&quot;//;s/&quot;$//&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> links.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 逐个核对目标文件是否真实存在（.html 或 dir/index.html）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>结果：约 <strong>774 个唯一站内目标，22 个死链</strong>。关键判断——这 22 个是否由本次改造引入？逐一查来源页面后发现，它们全部来自旧文章正文里指向「早年已删除的旧 AI 文档」的链接（在改造前的基线提交里目标就已不存在），<strong>属于历史遗留，非本次引入</strong>；新页面与 config 的死链为 0。</p><p>配套还有两条硬约束：</p><ul><li><strong>文章只增不减</strong>：改造前 445 篇 → 改造后 449 篇（新增项目页/文章/模板等），删除 0、迁移 0；</li><li><strong>可整体回退</strong>：改造前单独打一个基线提交，出问题整单回退。</li></ul><h2 id="五、结果与经验" tabindex="-1">五、结果与经验 <a class="header-anchor" href="#五、结果与经验" aria-label="Permalink to “五、结果与经验”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>改造前</th><th>改造后</th></tr></thead><tbody><tr><td>顶部栏目</td><td>6 项含 2 下拉</td><td><strong>5 项 0 下拉</strong></td></tr><tr><td>侧栏</td><td>按旧目录十几套</td><td>每栏目一套，技术知识归位</td></tr><tr><td>首页</td><td>「个人技术学习站」</td><td>求职定位 + 代表项目 + 联系方式</td></tr><tr><td>文章 URL</td><td>—</td><td><strong>0 变更</strong></td></tr><tr><td>死链</td><td>22 个历史遗留</td><td>新增 0（遗留项记录待治理）</td></tr></tbody></table><p><strong>几条可复用的经验</strong>：</p><ol><li><strong>先冻结范围再动手</strong>：第一天只做框架，不迁文件、不补内容，避免无限装修挤占真正能证明能力的项目时间。</li><li><strong>用产物验证，别用警告验证</strong>：dead-link 警告在带 <code>base</code> 的站点会误报，直接从构建产物 grep 链接再核对目标文件最可靠。</li><li><strong>「不搬文件」是迁移安全的最大杠杆</strong>：只改配置，URL 就不变，外链和 SEO 不受影响，回退也只需一个 commit。</li><li><strong>映射表先行</strong>：先盘清 445 篇的去向，再决定侧栏，避免「为了整齐而迁移」或「凭空造空页」。</li></ol><h2 id="六、局限与改进" tabindex="-1">六、局限与改进 <a class="header-anchor" href="#六、局限与改进" aria-label="Permalink to “六、局限与改进”">​</a></h2><ul><li>物理目录仍是旧名（<code>java</code> <code>framework</code> 等独立目录），后续若要做真正的路径治理，需配 301/别名并评估外链影响。</li><li>22 个历史死链尚未清理，列入了后续治理清单。</li><li><code>/more/</code> 是过渡方案，未归类内容仍需逐步归位。</li></ul><h2 id="七、相关" tabindex="-1">七、相关 <a class="header-anchor" href="#七、相关" aria-label="Permalink to “七、相关”">​</a></h2><ul><li>项目实践总览：<a href="/my-vitepress-site/apps/">应用开发</a></li><li>本改造的可勾选计划：<a href="/my-vitepress-site/plan/">30 天建设计划</a> · <a href="/my-vitepress-site/plan/mapping.html">内容映射表</a></li></ul>`,33)])])}const k=s(r,[["render",n]]);export{g as __pageData,k as default};
